/**
 * Fills the database with a handful of realistic demo jobs (PRD §9 "demo data").
 *
 * Uses the real service layer — not raw inserts — so job numbers come from
 * `Shop.jobSeq`, tokens are generated by the app, and status changes write the
 * same audit events a real owner action would. Safe to re-run: it exits early
 * once the demo customers are present.
 *
 *   npm run demo:seed
 */
import { eq } from "drizzle-orm";

import { getDb } from "../src/lib/db/index";
import { jobs, shops } from "../src/lib/db/schema";
import { normalisePhone } from "../src/lib/phone";
import { createJob, updateJob } from "../src/lib/services/jobs";
import type { JobStatus } from "../src/lib/status";
import { runScript } from "./_run";

type DemoJob = {
  customerName: string;
  customerPhone: string;
  itemName: string;
  issue: string;
  estimateDays: number;
  /** Applied after creation, in order, so the timeline looks lived-in. */
  history: JobStatus[];
  publicNote?: string;
};

const DEMO_JOBS: DemoJob[] = [
  {
    customerName: "Muhammad Asif",
    customerPhone: "03335550101",
    itemName: "Geyser",
    issue: "Pani garam nahi ho raha",
    estimateDays: 2,
    history: ["IN_REPAIR"],
    publicNote: "Thermostat badal raha hai, kal tak ho jayega.",
  },
  {
    customerName: "Sadia Bibi",
    customerPhone: "03335550102",
    itemName: "Juicer",
    issue: "Motor se awaz aa rahi hai",
    estimateDays: 4,
    history: ["IN_REPAIR", "WAITING_FOR_PART"],
    publicNote: "Motor ka part order kar diya hai.",
  },
  {
    customerName: "Imran Khan",
    customerPhone: "03335550103",
    itemName: "Heater",
    issue: "On nahi ho raha",
    estimateDays: 1,
    history: ["IN_REPAIR", "READY"],
    publicNote: "Heater theek ho gaya hai, dukan se le jayein.",
  },
  {
    customerName: "Naveed Ahmed",
    customerPhone: "03335550104",
    itemName: "Fan",
    issue: "Speed kam hai",
    estimateDays: 3,
    history: ["IN_REPAIR", "READY", "DELIVERED"],
  },
];

async function main(): Promise<void> {
  const db = await getDb();
  const shop = await db.query.shops.findFirst();
  if (!shop) throw new Error("No shop found — run `npm run db:seed` first.");

  // An owner with real jobs should not get demo customers mixed in, so the
  // script only seeds a genuinely empty board.
  const existing = await db
    .select({ customerPhone: jobs.customerPhone })
    .from(jobs)
    .where(eq(jobs.shopId, shop.id))
    .limit(50);

  // Stored numbers are E.164, so compare normalised values — otherwise a
  // second run would happily create a duplicate of every demo job.
  const alreadySeeded = new Set(existing.map((row) => row.customerPhone));
  let created = 0;

  for (const demo of DEMO_JOBS) {
    const phone = normalisePhone(demo.customerPhone);
    if (phone && alreadySeeded.has(phone)) continue;

    let job = await createJob({
      shopId: shop.id,
      input: {
        customerName: demo.customerName,
        customerPhone: demo.customerPhone,
        itemName: demo.itemName,
        issue: demo.issue,
        estimateDays: demo.estimateDays,
        internalNote: null,
      },
    });
    created += 1;

    for (const [index, status] of demo.history.entries()) {
      const isLast = index === demo.history.length - 1;
      job = (
        await updateJob({
          shopId: shop.id,
          jobId: job.id,
          patch: {
            status,
            ...(isLast && demo.publicNote ? { publicNote: demo.publicNote } : {}),
          },
        })
      ).job;
    }

    console.log(
      `[demo] #${job.jobNumber} ${job.status.padEnd(16)} ${job.itemName} — ${job.customerName}`,
    );
    console.log(`[demo]   /s/${job.publicToken}`);
  }

  if (created === 0) {
    console.log("[demo] demo jobs already present, nothing to do");
  } else {
    const [fresh] = await db
      .select({ jobSeq: shops.jobSeq })
      .from(shops)
      .where(eq(shops.id, shop.id))
      .limit(1);
    console.log(`[demo] created ${created} job(s); next job number is ${(fresh?.jobSeq ?? 0) + 1}`);
  }

  process.exit(0);
}

runScript("demo", main);
